-- 0. RECONCILE SCHEMA & RECREATE EMPTY TABLES WITH FLEXIBLE IDS & FULL COLUMNS
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

DROP TABLE IF EXISTS audit_logs, email_logs, payment_allocations, advance_adjustments, advance_balances, wallet_transactions, maintenance_payments, maintenance_invoices, maintenance_rate_history, maintenance_settings, society_expenses, expense_categories, flat_resident_history, residents, flats, floors, societies CASCADE;

-- 1. SOCIETIES TABLE
CREATE TABLE societies (
    id VARCHAR(100) PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    society_name VARCHAR(255) NOT NULL,
    address TEXT NOT NULL,
    city VARCHAR(100) NOT NULL DEFAULT 'Pune',
    state VARCHAR(100) NOT NULL DEFAULT 'Maharashtra',
    pincode VARCHAR(20) NOT NULL DEFAULT '411038',
    email VARCHAR(255) NOT NULL DEFAULT 'parijatsociety@gmail.com',
    contact_number VARCHAR(50),
    financial_year VARCHAR(50) NOT NULL DEFAULT '2026-2027',
    opening_balance DECIMAL(14, 2) NOT NULL DEFAULT 0.00,
    opening_balance_date DATE NOT NULL DEFAULT '2025-09-01',
    bank_name VARCHAR(255) NOT NULL DEFAULT 'HDFC Bank',
    account_holder_name VARCHAR(255) NOT NULL DEFAULT 'Parijat Cooperative Housing Society Ltd',
    account_number VARCHAR(100) NOT NULL DEFAULT '5020008910291',
    ifsc_code VARCHAR(50) NOT NULL DEFAULT 'HDFC0001234',
    branch_name VARCHAR(255) NOT NULL DEFAULT 'Kothrud Branch, Pune',
    upi_id VARCHAR(255) NOT NULL DEFAULT 'parijatsociety@okhdfcbank',
    qr_code_url TEXT DEFAULT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 2. FLOORS TABLE
CREATE TABLE floors (
    id VARCHAR(100) PRIMARY KEY,
    society_id VARCHAR(100) NOT NULL REFERENCES societies(id) ON DELETE CASCADE,
    floor_number INT NOT NULL,
    floor_name VARCHAR(100) NOT NULL,
    description TEXT,
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    is_archived BOOLEAN NOT NULL DEFAULT FALSE,
    total_flats INT NOT NULL DEFAULT 4,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (society_id, floor_number)
);

-- 3. FLATS TABLE
CREATE TABLE flats (
    id VARCHAR(100) PRIMARY KEY,
    society_id VARCHAR(100) NOT NULL REFERENCES societies(id) ON DELETE CASCADE,
    floor_id VARCHAR(100) NOT NULL REFERENCES floors(id) ON DELETE RESTRICT,
    flat_number VARCHAR(50) NOT NULL,
    flat_type VARCHAR(50) DEFAULT '2BHK',
    area_sqft DECIMAL(10, 2) DEFAULT 850.00,
    maintenance_override DECIMAL(10, 2) DEFAULT NULL,
    advance_balance DECIMAL(10, 2) NOT NULL DEFAULT 0.00,
    outstanding_dues DECIMAL(10, 2) NOT NULL DEFAULT 0.00,
    status VARCHAR(30) NOT NULL DEFAULT 'OCCUPIED',
    description TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (society_id, flat_number)
);

-- 4. RESIDENTS TABLE
CREATE TABLE residents (
    id VARCHAR(100) PRIMARY KEY,
    society_id VARCHAR(100) REFERENCES societies(id) ON DELETE CASCADE,
    flat_id VARCHAR(100) NOT NULL REFERENCES flats(id) ON DELETE CASCADE,
    full_name VARCHAR(255) NOT NULL,
    resident_type VARCHAR(20) NOT NULL DEFAULT 'OWNER',
    email VARCHAR(255),
    mobile VARCHAR(50),
    mobile_number VARCHAR(50),
    alternate_mobile VARCHAR(50),
    move_in_date DATE DEFAULT '2025-09-01',
    move_out_date DATE DEFAULT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 5. EXPENSE CATEGORIES TABLE
CREATE TABLE expense_categories (
    id VARCHAR(100) PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 6. SOCIETY EXPENSES TABLE
CREATE TABLE society_expenses (
    id VARCHAR(100) PRIMARY KEY,
    society_id VARCHAR(100) NOT NULL REFERENCES societies(id) ON DELETE CASCADE,
    category_id VARCHAR(100) NOT NULL REFERENCES expense_categories(id) ON DELETE RESTRICT,
    title VARCHAR(255) NOT NULL,
    amount DECIMAL(12, 2) NOT NULL,
    expense_date DATE NOT NULL,
    payment_method VARCHAR(50) NOT NULL DEFAULT 'ONLINE',
    vendor_name VARCHAR(255) DEFAULT 'Local Vendor',
    invoice_bill_no VARCHAR(100),
    attachment_url TEXT,
    description TEXT,
    created_by VARCHAR(255) DEFAULT 'System Seeder',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 7. MAINTENANCE PAYMENTS TABLE
CREATE TABLE maintenance_payments (
    id VARCHAR(100) PRIMARY KEY,
    society_id VARCHAR(100) REFERENCES societies(id) ON DELETE CASCADE,
    flat_id VARCHAR(100) NOT NULL REFERENCES flats(id) ON DELETE CASCADE,
    resident_id VARCHAR(100) REFERENCES residents(id) ON DELETE SET NULL,
    receipt_number VARCHAR(100) NOT NULL UNIQUE,
    total_amount_received DECIMAL(10, 2) NOT NULL,
    amount DECIMAL(10, 2) NOT NULL,
    payment_date DATE NOT NULL,
    payment_method VARCHAR(50) NOT NULL DEFAULT 'ONLINE_UPI',
    transaction_ref VARCHAR(100),
    description TEXT,
    attachment_url TEXT,
    created_by VARCHAR(255) DEFAULT 'System Seeder',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 8. MAINTENANCE INVOICES TABLE
CREATE TABLE maintenance_invoices (
    id VARCHAR(100) PRIMARY KEY,
    society_id VARCHAR(100) REFERENCES societies(id) ON DELETE CASCADE,
    flat_id VARCHAR(100) NOT NULL REFERENCES flats(id) ON DELETE CASCADE,
    resident_id VARCHAR(100) REFERENCES residents(id) ON DELETE SET NULL,
    month INT NOT NULL,
    year INT NOT NULL,
    billing_month VARCHAR(20),
    invoice_amount DECIMAL(10, 2) NOT NULL DEFAULT 0.00,
    paid_amount DECIMAL(10, 2) NOT NULL DEFAULT 0.00,
    due_amount DECIMAL(10, 2) NOT NULL DEFAULT 0.00,
    status VARCHAR(30) NOT NULL DEFAULT 'NO_DUES',
    invoice_status VARCHAR(30) NOT NULL DEFAULT 'NO_DUES',
    due_date DATE NOT NULL,
    description TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (flat_id, year, month)
);

-- 9. WALLET TRANSACTIONS TABLE
CREATE TABLE wallet_transactions (
    id VARCHAR(100) PRIMARY KEY,
    society_id VARCHAR(100) NOT NULL REFERENCES societies(id) ON DELETE CASCADE,
    transaction_date DATE NOT NULL,
    transaction_type VARCHAR(20) NOT NULL CHECK (transaction_type IN ('CREDIT', 'DEBIT')),
    category VARCHAR(50) NOT NULL DEFAULT 'MAINTENANCE',
    amount DECIMAL(14, 2) NOT NULL,
    source_ref_id VARCHAR(100),
    running_balance DECIMAL(14, 2) NOT NULL DEFAULT 0.00,
    description TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 10. MAINTENANCE SETTINGS TABLE
CREATE TABLE maintenance_settings (
    id VARCHAR(100) PRIMARY KEY DEFAULT 'setting-1',
    society_id VARCHAR(100) NOT NULL REFERENCES societies(id) ON DELETE CASCADE,
    monthly_amount DECIMAL(10, 2) NOT NULL DEFAULT 1100.00,
    owner_monthly_amount DECIMAL(10, 2) NOT NULL DEFAULT 1000.00,
    tenant_monthly_amount DECIMAL(10, 2) NOT NULL DEFAULT 1100.00,
    due_day_of_month INT NOT NULL DEFAULT 10,
    currency VARCHAR(10) NOT NULL DEFAULT 'INR',
    late_fee_enabled BOOLEAN NOT NULL DEFAULT FALSE,
    late_fee_amount DECIMAL(10, 2) NOT NULL DEFAULT 0.00,
    reminder_days INT[] NOT NULL DEFAULT '{5, 10, 15, 20, 25, 30}',
    email_notifications_enabled BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

